/** Stage 1 declaration/literal proposal only. No driver or implementation.
 * Expected data and case labels MUST NOT be provided to fake ports. */
import type * as Effect from "effect/Effect";
import type * as Scope from "effect/Scope";
declare const sessionBrand: unique symbol;
declare const ioBrand: unique symbol;
declare const frameBrand: unique symbol;
declare const inspectionBrand: unique symbol;
declare const requestBrand: unique symbol;
declare const preparedBrand: unique symbol;
declare const leaseBrand: unique symbol;
declare const valueBrand: unique symbol;
declare const outputBrand: unique symbol;
declare const terminalBrand: unique symbol;
export interface OwnedSession { readonly [sessionBrand]: true }
export interface OwnedIo { readonly [ioBrand]: true }
export interface OwnedFrame { readonly [frameBrand]: true }
export interface OwnedInspection { readonly [inspectionBrand]: true }
export interface OwnedRequest { readonly [requestBrand]: true }
export interface OwnedPrepared { readonly [preparedBrand]: true }
export interface OwnedLease { readonly [leaseBrand]: true }
export interface OwnedValue { readonly [valueBrand]: true }
export interface OwnedOutput { readonly [outputBrand]: true }
export interface OwnedTerminal { readonly [terminalBrand]: true }
export type Code = "private_control_input" | "private_control_owned" | "private_control_busy" | "private_control_codec" | "private_control_authority" | "private_control_dispatch" | "private_control_sink" | "private_control_cleanup" | "private_control_unavailable" | "owned_handoff_closed";
export interface Failure { readonly code: Code }
export type Inspection = { readonly kind: "source_parse_error" } | {
 readonly kind: "parsed"; readonly rootObject: boolean; readonly version2: boolean;
 readonly method: string | null; readonly methodPresent: boolean;
 readonly id: { readonly present: false } | { readonly present: true; readonly canonicalEncoded: string; readonly scalar: "string" | "i64" | "u64" | "f64" | "invalid"; readonly valid: boolean };
 readonly cancellationTargetCanonicalEncoded: string | null;
};
export type Phase = "before_read" | "after_read" | "before_inspect" | "after_inspect" | "before_prepare" | "after_prepare" | "before_acquire" | "after_acquire" | "before_dispatch" | "after_dispatch" | "before_lazy_read" | "after_lazy_read" | "before_progress" | "after_progress" | "before_encode" | "after_encode" | "before_publication" | "after_publication" | "assert_current";
export interface InertView {
 frameText(frame: unknown): string | null;
 inspection(value: unknown): Inspection | null;
 prepared(value: unknown): PreparedView | null;
}
export interface AuthorizedView extends InertView {
 /** Own membership, original Scope, current caller/source/purpose/destination and independently
  * latest suppression authority checked on EACH authorized lazy read, before and after await. */
 /** Raw params slice (default {}). Common owner normalizes tool arguments; no eager frame JSON. */
 paramsText(request: unknown): Effect.Effect<string | null, Failure>;
 outputText(output: unknown): Effect.Effect<string | null, Failure>;
}
export interface Issuer {
 /** Bounded primitive private descriptor. Own callback, frame, factory and original Scope only. */
 inspection(frame: unknown, primitiveDescriptorUTF8: unknown): OwnedInspection | null;
 request(inspection: unknown): OwnedRequest | null;
 prepared(kind: unknown, request: unknown): OwnedPrepared | null;
 rejection(value: unknown): OwnedPrepared | null;
 /** Success/error tags are distinct own issuance; error-shaped success JSON stays success. */
 value(primitiveSourceJsonUTF8: unknown): OwnedValue | null;
 error(code: unknown, fixedMessage: unknown): OwnedValue | null;
 output(context: unknown, primitiveUTF8: unknown): OwnedOutput | null;
}
export type PreparedView = { readonly kind: "local" | "operation"; readonly request: OwnedRequest } | { readonly kind: "error"; readonly value: OwnedValue };
export interface TrustedDispatcher {
 /** Lossless source-semantic inspection only; no allocation/evaluation/ID reservation. Unknown
  * outcome accepted only if own callback-issued token; foreign/Proxy fails before properties. */
 inspect(frame: OwnedFrame, issuer: Issuer, view: InertView): unknown;
 /** New concurrent owned request seam: common owner normalizes methods/arguments and admits
  * current surface policy. Read-only denial precedes hidden mutation/pairing/export dispatch.
  * Control owns scheduling/admission/cancellation/session used IDs; no second evaluator.
  * prepare returns ONLY own callback-issued OwnedPrepared token, inspected by factory InertView.prepared(). */
 prepare(inspection: OwnedInspection, issuer: Issuer, view: AuthorizedView): Effect.Effect<unknown, Failure>;
 local(request: OwnedRequest, issuer: Issuer, view: AuthorizedView): Effect.Effect<OwnedValue, Failure>;
 acquire(request: OwnedRequest, view: InertView): Effect.Effect<unknown, Failure>;
 release(allocation: unknown): Effect.Effect<void, Failure>;
 /** Completed acquire+captured release registration atomically original-Scope owned. One
  * common operation executes, including cancellation behavior; controller never invents it. */
 execute(request: OwnedRequest, lease: OwnedLease, emit: (progress: OwnedValue) => Effect.Effect<void, Failure>, issuer: Issuer, view: AuthorizedView): Effect.Effect<OwnedValue, Failure>;
 /** Sole trusted renderer: own request result/error/progress token, no case/ID response table. */
 encode(context: OwnedInspection, value: OwnedValue, issuer: Issuer, view: AuthorizedView): unknown;
}
export interface CurrentAuthority {
 check(session: OwnedSession, request: OwnedRequest | null, phase: Phase, view: InertView): Effect.Effect<void, Failure>;
}
export interface IoMethods {
 /** Retained framing owner supplies decoded/trimmed lines. Bounded queue32; completed
  * private64KiB line gate before inspection. Native2MiB/lossy profile is separate owner. */
 read(issuer: { frame(primitiveUTF8: unknown): OwnedFrame | null }): Effect.Effect<OwnedFrame | null, Failure>;
 /** Single writer; encoded UTF8 + LF + flush ACK, bounded slow-sink backpressure. */
 publish(output: OwnedOutput, view: AuthorizedView): Effect.Effect<void, Failure>;
 release(): Effect.Effect<void, Failure>;
}
export interface IoIssuer {
 /** Trusted callback method table captured once; no properties read from returned unknown IO token. */
 own(methods: IoMethods): OwnedIo | null;
}
export interface IoOwner { acquire(issuer: IoIssuer): Effect.Effect<unknown, Failure> }
export interface TerminalView {
 readonly inputEOF: true; readonly operationReleaseACKs: number; readonly ioReleaseACK: true;
 readonly publication: "acknowledged_private_sink_only"; readonly durableJobCancellation: "unqualified";
}
export interface ControlSession {
 open(): Effect.Effect<OwnedSession, Failure, Scope.Scope>;
 run(session: unknown): Effect.Effect<OwnedTerminal, Failure>;
 inspectTerminal(terminal: unknown): TerminalView | null;
}
export interface ControlFactory {
 create(ports: { readonly owner: IoOwner; readonly dispatcher: TrustedDispatcher; readonly current: CurrentAuthority; readonly codecProfile: "existing_private_64KiB" }): Effect.Effect<ControlSession, Failure, Scope.Scope>;
}
export type Gate = "io_acquire" | "read" | "initialize" | "acquire" | "operation" | "release" | "progress" | "publish" | "io_release";
export type Callback = "io_acquire" | "read" | "inspect" | "prepare" | "local" | "acquire" | "dispatch" | "lazy_read" | "progress" | "encode" | "publish" | "release" | "io_release";
export type Action =
 | { readonly kind: "line"; readonly utf8: string }
 | { readonly kind: "lines"; readonly utf8: readonly string[]; readonly settleEach: boolean }
 | { readonly kind: "gate" | "ack"; readonly gate: Gate; readonly ordinal: number }
 | { readonly kind: "progress"; readonly operationOrdinal: number; readonly sourceJsonUTF8: readonly string[] }
 | { readonly kind: "checkpoint"; readonly label: string }
 | { readonly kind: "eof" | "interrupt" }
 | { readonly kind: "revoke"; readonly callback: Callback; readonly ordinal: number; readonly edge: "before" | "after"; readonly authority: "caller" | "source" | "purpose" | "destination" | "suppression" | "unavailable" }
 | { readonly kind: "close_scope"; readonly callback: Callback; readonly ordinal: number; readonly edge: "before" | "after" }
 | { readonly kind: "fault"; readonly callback: Callback; readonly ordinal: number; readonly outcome: "failure" | "defect" | "interrupt" | "cleanup_failure" | "cleanup_defect" | "foreign_return" | "proxy_return" | "foreign_session_return" | "own_issued_foreign_return" }
 | { readonly kind: "close_pending_scope"; readonly callback: "io_acquire"; readonly ordinal: number }
 | { readonly kind: "probe"; readonly target: "request" | "io" | "session" | "frame" | "inspection" | "prepared" | "lease" | "value" | "output" | "terminal" | "issuer" | "inert_view" | "authorized_view"; readonly provenance: "foreign" | "proxy" | "expired_callback" | "expired_scope" | "new_scope" | "reentrant" | "foreign_factory" | "foreign_session" | "foreign_request" | "live_callback_return" | "late_issue" | "malformed_issuance" | "current_revoked" | "current_unavailable" | "poisoned" };
export interface Snapshot {
 readonly label: string; readonly writesUTF8: readonly string[]; readonly active: number;
 readonly usedIds: number; readonly cancellationSignals: number; readonly acquired: number;
 readonly releaseACKs: number; readonly ioReleaseACKs: number; readonly terminated: boolean;
 readonly inputQueued: number; readonly notificationQueued: number;
 /** Explicit producer admission state, distinct from dequeued+gated sink item. */
 readonly progressAdmission?: { readonly attempted: number; readonly admitted: number; readonly blocked: boolean };
 readonly ioAllocation?: { readonly attempted: number; readonly completed: number; readonly registered: number; readonly releasePending: boolean };
}
export type End = { readonly kind: "acknowledged" } | { readonly kind: "failure"; readonly code: Code } | { readonly kind: "interrupted" };
export interface ControlVector {
 readonly case_id: string; readonly basis: string; readonly profile: "existing_private_64KiB";
 readonly surface: "local_direct" | "local_read_only" | "remote_read_only";
 readonly commonResultUTF8: string; readonly actions: readonly Action[];
 readonly expected: {
  readonly writesUTF8: readonly string[]; readonly snapshots: readonly Snapshot[]; readonly end: End;
  readonly probeOutcome: End | null;
  readonly ioAllocation?: { readonly attempted: number; readonly completed: number; readonly registered: number; readonly releasePending: boolean };
  readonly acquired: number; readonly releaseACKs: number; readonly ioReleaseACKs: number;
  readonly cancellationSignals: number; readonly usedIds: number; readonly forbiddenIoCalls: 0;
  readonly proxyTraps: 0; readonly durableJobCancelledClaim: false; readonly commonOperationOwners: 1;
 };
}

